import turtle
import time
turtle.tracer(0)
class 공:
    def __init__(self, dx, dy):
        self.몸 = turtle.Turtle()
        self.몸.shape("circle")
        self.몸.penup()
        self.dx = dx
        self.dy = dy
    def 움직이기(self):
        self.몸.setx(self.몸.xcor() + self.dx)
        self.몸.sety(self.몸.ycor() + self.dy)
        if self.몸.xcor() > 220 or self.몸.xcor() < -220:
            self.dx = -self.dx
        if self.몸.ycor() > 160 or self.몸.ycor() < -160:
            self.dy = -self.dy

공들 = [공(5, 3), 공(-4, 6)]
while True:
    for 한개 in 공들:
        한개.움직이기()
    turtle.update()
    time.sleep(0.02)
